import {hasWayglass} from './wayglass-model.js?v=5.11.0';
import {fibreAudit,starFibres} from './kakeya-math.js';
import {grantResonance} from './resonance-link.js';
export const LISTENINGS=[
 {id:'river',title:'The River’s Unanswered Name',chapters:[3,11,17],support:'echo',texts:['A hydrophone measures vibration in water. This maintenance plate names a second pipe: the return. Someone removed the valves that let the river districts answer.','Clay holds the reed; water carries its motion. Clay & Water was the workshop name for a two-way instrument, before the palace treated every home as an audience.','The prism gives each direction a shared place without making the directions identical. The Kakeya model is a design clue, not a command to put every voice in unison.']},
 {id:'hearth',title:'The Warmth Between Houses',chapters:[2,13,18],support:'echo',texts:['A household kiln bears two mouthpieces. One transmits; one receives. A home was meant to answer the city.','The Mako records a material pattern, not a dead person. Its repeated pulse stabilizes the reed while the speaker chooses the words.','An unfinished song leaves room for another household. The missing cadence was an invitation before the state called it a defect.']},
 {id:'bell',title:'The Space After the Bell',chapters:[4,16,23],support:'chain',texts:['The bell schedule includes a blank after each phrase. The blank was time reserved for an answer, not a missing note.','The hydrophone listens to pressure; the Wayglass shows mineral routes. Neither device can decide whose reply matters.','The city’s title, Ash & Aether, described what survives a furnace and what travels beyond it. The Unfinished Song names the space the living must fill themselves.']},
 {id:'orchard',title:'A Song That Can Grow',chapters:[7,19,23],support:'chain',texts:['A root graft shares water without making two trees one tree. The orchard engineers drew their answering network the same way.','Mako resonance holds a repeatable pattern. A living player can bend its timing; a captive recording cannot consent to being played forever.','The old score has separate parts with shared meeting points. Rebuilding the city means letting those parts leave the chord as well as join it.']},
 {id:'archive',title:'The Marks Beneath the Copy',chapters:[5,12,21],support:'break',texts:['Under the official score, an erased instruction reads: wait for the answer. The broadcast was made one-way by an edit.','The Wayglass separates directions in a mineral seam. The hydrophone separates a vibration from the water around it. Their evidence agrees; neither is a vessel for a soul.','Pottery marks identify the houses that owned the return valves. The mechanism was communal property before the crown copied its music and removed its replies.']},
 {id:'road',title:'The Order With a Return Address',chapters:[2,15,20],support:'break',texts:['A delivery order names both sender and receiver. The first hydrophone plans do too. The later plans erase the receiver’s return address.','The Mako, lens and reed each do a different job: hold a pattern, reveal its route, and put air or water in motion. None replaces the person who chooses to speak.','The final switch cannot restore the dead. It can return the right to answer to people who are still here. The unfinished phrase belongs to them.']}
];
const clone=x=>JSON.parse(JSON.stringify(x)),hash=s=>{let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;};
export function listeningLegacy(s){const history=clone(s?.encore?.history||[]);if(!s?.complete||s.chapter!==25)return s?.encore?clone(s.encore):null;
 const cycle=(s.encore?.cycle||0)+1,record={cycle,ending:s.story?.finalChoice||0,route:s.encore?.routeId||null,project:s.project||0,choices:clone(s.storyChoices||{}),restorations:[...(s.physicalLore?.completed||[])]};history.push(record);if(history.length>512)history.splice(0,history.length-512);
 const seed=hash(JSON.stringify(history)),counts=Object.fromEntries(LISTENINGS.map(r=>[r.id,history.filter(x=>x.route===r.id).length])),min=Math.min(...Object.values(counts)),pool=LISTENINGS.filter(r=>counts[r.id]===min&&r.id!==record.route);const route=(pool.length?pool:LISTENINGS.filter(r=>counts[r.id]===min))[seed%(pool.length||LISTENINGS.filter(r=>counts[r.id]===min).length)];
 return {version:1,cycle,seed,routeId:route.id,solved:[],history};
}
export const currentListening=s=>LISTENINGS.find(r=>r.id===s?.encore?.routeId);
const placements=new WeakMap();
export function validateListening(s){const e=s.encore;if(e===undefined||e===null)return;if(e.version!==1||!Number.isSafeInteger(e.cycle)||e.cycle<1||!Number.isInteger(e.seed)||e.seed<0||e.seed>0xffffffff||!LISTENINGS.some(r=>r.id===e.routeId)||!Array.isArray(e.history)||!e.history.length||e.history.length>512||e.history.some(r=>!r||typeof r!=='object'||Array.isArray(r)||r.ending!==undefined&&![0,1,2].includes(r.ending)||r.route!=null&&!LISTENINGS.some(route=>route.id===r.route))||!Array.isArray(e.solved)||e.solved.some(n=>![0,1,2].includes(n))||new Set(e.solved).size!==e.solved.length)throw Error('Invalid listening history');}
/** Reuse an existing reachable approach tile beside an authored object, never alter collision. */
export function listeningObjects(w){const r=currentListening(w.state);if(!r||w.state.chronicle?.phase==='past'||!hasWayglass(w.state))return [];const index=r.chapters.indexOf(w.scene.chapter);if(index<0||w.state.encore.solved.includes(index)||w.state.chapter<r.chapters[index]||w.scene.biome)return [];
 let cache=placements.get(w.data);if(!cache){cache=new Map();placements.set(w.data,cache);}const cacheKey=r.id+':'+w.state.encore.seed+':'+index;if(cache.has(cacheKey)){const o=cache.get(cacheKey);return o&&o.encoreScene===w.scene.location?[{...o,xy:[...o.xy]}]:[];}const rooms=w.data.scenes.filter(s=>s.chapter===r.chapters[index]&&!s.originId&&!s.biome);rooms.sort((a,b)=>(a.key==='archive'?-2:a.key==='workshop'?-1:0)-(b.key==='archive'?-2:b.key==='workshop'?-1:0));for(const scene of rooms){
 const arrive=scene.arrive||[1,1],starts=[];for(let y=1;y<scene.height-1;y++)for(let x=1;x<scene.width-1;x++)if(scene.floor[y]?.[x]!=='#')starts.push([x,y]);starts.sort((a,b)=>Math.hypot(a[0]-arrive[0],a[1]-arrive[1])-Math.hypot(b[0]-arrive[0],b[1]-arrive[1]));if(!starts.length)continue;const start=starts[0],seen=new Set(),q=[start],cells=[];for(let i=0;i<q.length;i++){const [x,y]=q[i],key=x+','+y;if(seen.has(key)||x<0||y<0||x>=scene.width||y>=scene.height||scene.floor[y]?.[x]==='#')continue;seen.add(key);cells.push([x,y]);for(const d of [[1,0],[-1,0],[0,1],[0,-1]])q.push([x+d[0],y+d[1]]);}
 const free=cells.filter(([x,y])=>x>0&&y>0&&x<scene.width-1&&y<scene.height-1&&!scene.objects.some(o=>o.xy&&Math.hypot(o.xy[0]-x,o.xy[1]-y)<1.5));if(!free.length)continue;const xy=free[(w.state.encore.seed+index)%free.length],o={type:'note',label:'An answering reed',xy,encoreIndex:index,encoreScene:scene.location,text:r.texts[index]};cache.set(cacheKey,o);return scene.location===w.scene.location?[{...o,xy:[...xy]}]:[];}cache.set(cacheKey,null);return [];
}
export function listeningInteraction(w,o){if(o.encoreIndex===undefined)return false;const current=listeningObjects(w).find(x=>x.encoreIndex===o.encoreIndex&&x.xy.join()===o.xy?.join());if(!current)return true;const r=currentListening(w.state),index=o.encoreIndex,d=(w.state.encore.seed+index)%3+1,assign=[1,2,3];assign[d-1]=d%3+1;
 w.choose('The Wayglass shows three shared directions. Direction '+d+' has been copied onto the wrong return. Which direction should this reed carry?', [1,2,3].map(answer=>['Direction '+answer,()=>{const fixed=[...assign];fixed[d-1]=answer;if(fibreAudit(starFibres(2,fixed),2).covered!==3)return w.text('One direction still has no shared return. Inspect the reed again.');if(w.state.encore.solved.includes(index))return;w.state.encore.solved.push(index);grantResonance(w.state,{sourceId:'listening:'+w.state.encore.cycle+':'+index,label:r.title+' · answering reed',points:1});const all=w.state.encore.solved.length===3;if(all){grantResonance(w.state,{sourceId:'listening:'+w.state.encore.cycle+':complete',label:'Three return channels restored',points:2});if(!w.state.supports.includes(r.support))w.state.supports.push(r.support);}w.state.story.journal.push({id:'listening:'+index,chapter:w.state.chapter,title:r.title,text:current.text});const last=w.state.encore.history.at(-1);w.text([current.text,...(all?[last?.ending===1?'Your earlier journey kept the family’s song private. These repairs do not undo that choice.':last?.ending===2?'Your earlier journey let the city hear the song once. These repairs do not make that consent permanent.':'The earlier account leaves its final choice unrecorded.', 'Three return channels restored · 5 growth earned across the route · '+r.support+' support available.']:[])]);} ]));return true;
}
export function listeningLedger(w){const r=currentListening(w.state);if(!r)return ['Another Listening begins after a completed campaign. Choose a life in Other Lives & New Game Plus; its new route carries forward your ending and earlier decisions.'];return [r.title+' · Listening '+w.state.encore.cycle+' · '+w.state.encore.solved.length+'/3 answering reeds', 'Carry Rook’s Wayglass into chapters '+r.chapters.join(', ')+'. Look for an answering reed in a main room. This optional route does not replace your chosen origin or its consequences.',...w.state.story.journal.filter(x=>x.id.startsWith('listening:')).map(x=>x.text)];}
export function listeningEpilogue(s){const r=currentListening(s);return r&&s.encore.solved.length===3?['The three repaired return channels answer separately. '+r.title+' is entered in the city ledger. The score leaves their next phrase unwritten.']:[];}
